export interface Customer {
  id: string;
  external_id: string;
  name: string;
  email: string;
  payment_method: string;
  create_time: string | null;
  /** ISO 3166-1 alpha-2 */
  country: string;
  /** ISO 4217 */
  billing_currency: string;
  address: Address | null;
  tax_id: string;
  tax_office: string;
  e_invoice_registered: boolean;
  /** The language of the customer's mails, receipts and payment pages: en, tr, de, fr, es or ar. Empty is the browser's language (pages) and English (mails). */
  locale: string;
  /** individual (a person) or business (a taxpayer with a tax id). Empty is unknown. */
  customer_type: string;
  /** Set while the customer is blocked: no new subscription, plan change or purchase (existing subscriptions run on). A block whose blocked_until has passed has ended, whatever this says. */
  block_time?: string | null;
  /** The seller's own note on the block; never shown to the customer. */
  block_reason: string;
  /** Why: fraud, chargeback, abuse, request or other; empty when none was given. */
  block_category: string;
  /** When the block ends by itself; absent: until it is lifted. */
  blocked_until?: string | null;
  /** The block also suspends the customer's service: every entitlement check answers allowed false. Read it with block_time and blocked_until, it holds only while the block does. */
  service_suspended: boolean;
  /** The customer's mobile number as E.164 (+905321234567); empty when none. */
  phone: string;
  /** When tax_id last passed the local check (a TCKN or VKN checksum, the shape of a European VAT id). Not a registry lookup: no VIES, no GİB query. Absent when the id is empty or not recognised. */
  tax_id_validated_at?: string | null;
  /** One of tr_individual, tr_business, tr_any, tr_is_tckn, tr_is_vkn, eu_vat, or empty. A hint, never a refusal: the id does not look like the kind of number this customer should have (tr_individual: not a TCKN; tr_business: not a VKN; tr_any: neither; tr_is_tckn: a business was given a TCKN; tr_is_vkn: an individual was given a VKN; eu_vat: a business in the EU has no VAT id of its country's shape). Worked out from the stored id, country and customer_type, so it follows a change of any of them. Empty: nothing to say. */
  tax_id_warning: string;
  /** The customer has had a trial (a subscription that was ever trialing, cancelled ones included). Filled by GET /v1/customers/{external_id}; false in lists */
  trial_used: boolean;
}

