export interface PaymentLink {
  id: string;
  kind: "invoice" | "adhoc" | "credit_pack";
  /** paid: a single-use link that was paid */
  status: "active" | "paid" | "expired" | "revoked";
  /** kind credit_pack: the pack sold */
  pack_id: string;
  /** kind credit_pack: how many packs one use buys */
  quantity: number;
  /** kind credit_pack: the credits one paid use grants (the pack's credits times the quantity, frozen when the link was made); int64 as a string */
  credits: Int64;
  /** The code the seller chose for the link (adhoc and credit_pack): applied when the payer continues, unless the payer types another */
  promotion_code: string;
  /** The agreements the payer accepts on this link's page instead of the seller's tenant-wide setting (GET /v1/contracts/settings); empty: the setting applies */
  required_contracts: Array<"distance_sales" | "pre_info" | "tos" | "privacy">;
  /** The "return to app" address this link's page offers instead of the app's setting; empty: the app's */
  return_url: string;
  /** kind invoice: the invoice; empty for an ad-hoc link (its invoices are made on use) */
  invoice_id: string;
  customer_external_id: string;
  single_use: boolean;
  /** kind adhoc: int64 minor units as a string */
  amount_minor: Int64;
  currency: string;
  description: string;
  create_time: string | null;
  expire_time: string | null;
  revoke_time: string | null;
  /** Invoices paid through the link */
  paid_count: number;
  last_paid_time: string | null;
  /** Invoices the link created (ad hoc) */
  use_count: number;
  idempotency_key: string;
  /** kind adhoc: the order. Unit prices include VAT; the invoice has a line per item and the VAT per rate. A link with items is single-use and needs a buyer, a billing address and customer_external_id or customer_email */
  items?: Array<LinkItem>;
  /** kind adhoc: the buyer's e-mail; finds or makes the customer when customer_external_id is not given */
  customer_email?: string;
  /** kind adhoc: the shop's own reference for the order; goes to the invoice, the webhook events and the return URL */
  order_ref?: string;
  buyer?: LinkBuyer;
}

export interface PaymentMethodSetup {
  /** The provider's page: send it to the customer */
  url: string;
  /** The provider's reference of the page (Stripe's Checkout Session id) */
  ref: string;
}

export interface PaymentWait {
  /** The invoice's saga state (`Invoice.saga_state`). Everything below is set only for PAYMENT_HELD and PAYMENT_ACTION_REQUIRED */
  state: string;
  /** When the payment began to wait. For PAYMENT_ACTION_REQUIRED, the moment the mail asking the customer to confirm it was asked for (not proof that it was delivered) */
  since_time?: string;
  /** When Payrudder looks again (the next pass over held charges, or the next question to the provider) */
  next_check_time?: string;
  /** PAYMENT_HELD only, asked of the payment gate now. `customer_blocked`: the customer is blocked for fraud or a chargeback. `tenant_on_hold`: the operator has suspended, frozen or banned the environment. `none`: nothing holds it now, the next pass charges it. Absent when the gate could not be asked */
  hold_reason?: "customer_blocked" | "tenant_on_hold" | "none";
  /** PAYMENT_ACTION_REQUIRED only: when the payment counts as declined if the customer has not confirmed it. Absent when the payment service did not answer */
  window_ends_time?: string;
}

