export interface PublishPlanVersionRequest {
  base_fee_minor?: Int64;
  /** Fixed fees other than the tenant currency's monthly one (base_fee_minor), per currency and interval; no duplicates. A yearly subscription needs a yearly fee in its currency, including the tenant's */
  fees?: Array<CurrencyFeeInput>;
  prices?: Array<PriceInput>;
  entitlements?: Array<EntitlementInput>;
  /** The trial a new subscription to this version gets unless its request says otherwise; 0 is none */
  trial_days?: number;
  /** Left out: true. When a trial ends inside a billing period, charge the first period from the trial's end to the period's end instead of the whole fee; false charges the whole fee as versions published before this rule do */
  prorate_after_trial?: boolean;
  /** Left out: false. A customer who has had a trial before (any subscription that was ever trialing, cancelled ones included) gets no trial from this version: the subscription starts active and says trial_skipped already_used. A request's own trial_days is not checked */
  trial_once_per_customer?: boolean;
  /** Limits while a subscription to this version is trialing, one per meter, on meters the version prices or limits. Needs trial_days above 0. A meter left out keeps its normal limit during the trial; a customer's override still wins */
  trial_entitlements?: Array<EntitlementInput>;
  /** Credits a subscription gets for each paid fee period (with the period's invoice payment; at once for a free one); 0 or left out: none. An upgrade tops up the difference at once */
  included_credits?: Int64;
  /** After a period's grant the customer keeps at most this many plan credits; the oldest beyond it are written off (never what a hold set aside, never purchased or granted credits). 0 or left out: no cap; else at least included_credits */
  credit_rollover_cap?: Int64;
}

export interface PublishPlanVersionRequestParams {
  base_fee_minor?: Int64Input;
  /** Fixed fees other than the tenant currency's monthly one (base_fee_minor), per currency and interval; no duplicates. A yearly subscription needs a yearly fee in its currency, including the tenant's */
  fees?: Array<CurrencyFeeInputParams>;
  prices?: Array<PriceInputParams>;
  entitlements?: Array<EntitlementInput>;
  /** The trial a new subscription to this version gets unless its request says otherwise; 0 is none */
  trial_days?: number;
  /** Left out: true. When a trial ends inside a billing period, charge the first period from the trial's end to the period's end instead of the whole fee; false charges the whole fee as versions published before this rule do */
  prorate_after_trial?: boolean;
  /** Left out: false. A customer who has had a trial before (any subscription that was ever trialing, cancelled ones included) gets no trial from this version: the subscription starts active and says trial_skipped already_used. A request's own trial_days is not checked */
  trial_once_per_customer?: boolean;
  /** Limits while a subscription to this version is trialing, one per meter, on meters the version prices or limits. Needs trial_days above 0. A meter left out keeps its normal limit during the trial; a customer's override still wins */
  trial_entitlements?: Array<EntitlementInput>;
  /** Credits a subscription gets for each paid fee period (with the period's invoice payment; at once for a free one); 0 or left out: none. An upgrade tops up the difference at once */
  included_credits?: Int64Input;
  /** After a period's grant the customer keeps at most this many plan credits; the oldest beyond it are written off (never what a hold set aside, never purchased or granted credits). 0 or left out: no cap; else at least included_credits */
  credit_rollover_cap?: Int64Input;
}

/**
 * What reaching the limit means for `allowed` (Payrudder never refuses usage events). HARD (also unspecified): allowed turns false at the
 * limit. SOFT: allowed stays true and the usage over the limit is billed at the meter's price, which the package must have. NOTIFY: allowed
 * stays true; only the alerts are sent.
 *
 */
export type QuotaMode = "QUOTA_MODE_UNSPECIFIED" | "QUOTA_MODE_HARD" | "QUOTA_MODE_SOFT" | "QUOTA_MODE_NOTIFY";

/** What a limit counts over, in the tenant's time zone. Unspecified is the month (the billing period). A year is the calendar year (twelve billing periods); a lifetime limit never starts again. */
export type QuotaWindow = "QUOTA_WINDOW_UNSPECIFIED" | "QUOTA_WINDOW_MONTH" | "QUOTA_WINDOW_HOUR" | "QUOTA_WINDOW_DAY" | "QUOTA_WINDOW_WEEK" | "QUOTA_WINDOW_YEAR" | "QUOTA_WINDOW_LIFETIME";

