export interface SchedulePriceChangeRequest {
  /** The plan version the subscriptions are on now */
  from_version: number;
  /** The version they move to; 0 or absent is the latest published */
  to_version?: number;
  /** Days before the new price starts that the customer must be told at the least: absent or 0 is the platform's default (30 until the operator changes it), otherwise at least 14. A customer in a country with a longer minimum (the operator's table) is told that much earlier, or skipped as `renews_soon`. */
  notice_days?: number;
  /** The date the new price starts from. Each subscription then moves on its first period start on or after it (a monthly one on the first renewal from that date, a yearly one perhaps months later) instead of on its next renewal. At least `notice_days` from now and at most two years. A run that continues an open price change must name the date that price change has, or none if it has none (409 `plans.price_change.date_differs`). */
  effective_from?: string | null;
  /** Optional: send each customer's notice mail this many days before their new price starts, instead of when the run schedules it. Absent or 0 sends at once; otherwise at least `notice_days` and at most 365. A customer is never told later than their notice (the longer of `notice_days` and the minimum of their country), and a mail that is due already goes at once. A held mail waits in the price change and is sent by a sweep within minutes of its time; withdrawing the price change cancels it, and the operator's kill switch holds it. A run that continues an open price change must name the same value (409 `plans.price_change.date_differs`). */
  notice_send_days_before?: number;
  /** Only count; change nothing and mail nobody */
  dry_run?: boolean;
}

export interface SchedulePriceChangeResponse {
  /** Scheduled by this run */
  scheduled: number;
  scheduled_subscription_ids: Array<string>;
  skipped: Array<PriceChangeSkipped>;
  to_version: number;
  notice_days: number;
  /** The price change this run made or continued; empty for a dry run when none is open */
  price_change_id?: string;
  /** Scheduled by this price change before: not scheduled or mailed again */
  already_scheduled?: number;
}

